// Prepara os dados para o email de alerta ao responsavel interno
const inc = $input.first().json.body || $input.first().json;

// Texto de risco colorido (HTML)
const corRisco = inc.prob_final_pct > 60 ? '#d32f2f' : inc.prob_final_pct > 40 ? '#f57c00' : '#388e3c';
const nivelRisco = inc.prob_final_pct > 60 ? 'CRITICO' : inc.prob_final_pct > 40 ? 'ALTO' : 'MEDIO';

// Montar tabela de pedidos por mes
const pm = inc.pedidos_por_mes || {};
const tabelaPedidos = '<table style="width:100%;border-collapse:collapse;">'
  + '<tr style="background:#1976d2;color:white;"><th style="padding:6px;">Mês</th><th style="padding:6px;">Pedidos</th><th style="padding:6px;">Peças</th><th style="padding:6px;">Risco</th></tr>'
  + '<tr><td style="padding:6px;border:1px solid #ddd;">Mês 1 (0-30 dias)</td><td style="padding:6px;border:1px solid #ddd;">' + ((pm[1]||{}).pedidos||[]).length + '</td><td style="padding:6px;border:1px solid #ddd;">' + ((pm[1]||{}).qtd||0) + '</td><td style="padding:6px;border:1px solid #ddd;font-weight:bold;">' + Math.round(((pm[1]||{}).risco||0)*100) + '%</td></tr>'
  + '<tr style="background:#f5f5f5;"><td style="padding:6px;border:1px solid #ddd;">Mês 2 (31-60 dias)</td><td style="padding:6px;border:1px solid #ddd;">' + ((pm[2]||{}).pedidos||[]).length + '</td><td style="padding:6px;border:1px solid #ddd;">' + ((pm[2]||{}).qtd||0) + '</td><td style="padding:6px;border:1px solid #ddd;font-weight:bold;">' + Math.round(((pm[2]||{}).risco||0)*100) + '%</td></tr>'
  + '<tr><td style="padding:6px;border:1px solid #ddd;">Mês 3 (61-90 dias)</td><td style="padding:6px;border:1px solid #ddd;">' + ((pm[3]||{}).pedidos||[]).length + '</td><td style="padding:6px;border:1px solid #ddd;">' + ((pm[3]||{}).qtd||0) + '</td><td style="padding:6px;border:1px solid #ddd;font-weight:bold;">' + Math.round(((pm[3]||{}).risco||0)*100) + '%</td></tr>'
  + '</table>';

// Checklist formatado em HTML
const checklistItems = (inc.checklist_itens||[]).map((it, idx) =>
  '<li style="margin-bottom:8px;"><b>' + (idx+1) + '. ' + (it.ponto_verificacao||'') + '</b><br/>'
  + '<small>Critério: ' + (it.criterio_aceite||'') + ' | Freq: ' + (it.frequencia||'') + ' | Resp: ' + (it.responsavel||'') + '</small></li>'
).join('');

const email_assunto = '[RISCO ' + nivelRisco + ' ' + inc.prob_final_pct + '%] Fornecedor: ' + (inc.Fornecedor||'') + ' | Part: ' + (inc.Part_Number||'');

return [{
  json: {
    ...inc,
    email_assunto,
    nivel_risco: nivelRisco,
    cor_risco: corRisco,
    tabela_pedidos_html: tabelaPedidos,
    checklist_html: '<ol>' + checklistItems + '</ol>',
    email_responsavel: 'SEU_EMAIL_RESPONSAVEL@empresa.com',
    timestamp_alerta: new Date().toISOString()
  }
}];

// Recupera os dados do incidente (preservados no inicio da execucao)
// e monta o email para o fornecedor com o checklist LPC
const decisao = $input.first().json;
// Os dados do incidente estao na execucao - recuperar do nó Preparar Dados do Alerta
const inc = $('Preparar Dados do Alerta').first().json;

const dataLimite = new Date(Date.now() + 14 * 86400000).toLocaleDateString('pt-BR');
const checklistItemsHtml = (inc.checklist_itens||[]).map((it, idx) =>
  '<tr style="background:' + (idx%2===0?'white':'#f9f9f9') + ';">'
  + '<td style="padding:8px;border:1px solid #ddd;text-align:center;font-weight:bold;">' + (idx+1) + '</td>'
  + '<td style="padding:8px;border:1px solid #ddd;"><b>' + (it.ponto_verificacao||'') + '</b><br/><small>Categoria: ' + (it.categoria||'Processo') + '</small></td>'
  + '<td style="padding:8px;border:1px solid #ddd;">' + (it.criterio_aceite||'') + '</td>'
  + '<td style="padding:8px;border:1px solid #ddd;text-align:center;">' + (it.frequencia||'Por lote') + '</td>'
  + '<td style="padding:8px;border:1px solid #ddd;text-align:center;">' + (it.responsavel||'Operador') + '</td>'
  + '<td style="padding:8px;border:1px solid #ddd;text-align:center;">☐</td>'
  + '</tr>'
).join('');

const checklist_id = 'CKL-' + String(inc.ID||'000') + '-' + Date.now();

return [{
  json: {
    ...inc,
    checklist_id,
    data_limite_resposta: dataLimite,
    decisao_responsavel: 'APROVADO',
    timestamp_envio_fornecedor: new Date().toISOString(),
    email_assunto_fornecedor: '[LPC REQUEST] Layer Process Confirmation - Part: ' + (inc.Part_Number||'') + ' | ' + (inc.checklist_titulo||''),
    checklist_tabela_html: '<table style="width:100%;border-collapse:collapse;">'
      + '<tr style="background:#1565c0;color:white;"><th style="padding:8px;">#</th><th style="padding:8px;">Ponto de Verificação</th><th style="padding:8px;">Critério de Aceite</th><th style="padding:8px;">Frequência</th><th style="padding:8px;">Responsável</th><th style="padding:8px;">OK ✓</th></tr>'
      + checklistItemsHtml
      + '</table>',
    link_formulario_resposta: 'URL_DO_FORMULARIO_MICROSOFT_FORMS_AQUI'
  }
}];

const inc = $('Preparar Dados do Alerta').first().json;
return [{
  json: {
    ...inc,
    checklist_id: 'CKL-' + String(inc.ID||'000') + '-' + Date.now(),
    decisao_responsavel: 'REJEITADO',
    motivo_rejeicao: 'Responsavel optou por monitoramento sem acao direta',
    timestamp_decisao: new Date().toISOString()
  }
}];
